//! PGO branch profiling benchmark: skeleton vs skeleton+PGO vs native.
//!
//! Three execution modes compared:
//! 1. Native interpreter (baseline)
//! 2. Skeleton JIT (no PGO)
//! 3. Skeleton JIT + PGO (branch weight hints from profiled JUMPI)
//!
//! Requires a profile file generated by `collect_profile`:
//!   /tmp/branch_profile_{block}.bin
//!
//! Usage:
//!   cargo run -p revmc-examples-runner --bin pgo_bench --release [bench_dir] [block]

#[allow(dead_code)]
#[path = "../bin_common.rs"]
mod bin_common;

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{Duration, Instant};

use op_revm::transaction::OpTransaction;
use op_revm::DefaultOp;
use revm::bytecode::Bytecode;
use revm::database::EmptyDB;
use revm::handler::{EvmTr, FrameResult, Handler, ItemOrResult};
use revm::primitives::B256;
use revmc::profile::BranchProfile;
use revmc::skeleton::{analyze_skeleton_group, build_data_table, SkeletonVariance};
use revmc::{EvmCompiler, EvmLlvmBackend, OptimizationLevel};
use revmc_builtins as _;
use revmc_context::{EvmCompilerFn, RawEvmCompilerFn};
use serde::{Deserialize, Serialize};

use bin_common::{
    build_op_cfg, build_op_tx, compile_all_contracts_with_cache, extract_gas, BenchEvm,
    BenchError, BinLoader, NativeHandler, OpCtx,
};

const OPT: OptimizationLevel = OptimizationLevel::Aggressive;
const WARMUP_ROUNDS: usize = 5;
const MEASURE_ROUNDS: usize = 10;

// ── Serializable profile (must match collect_profile.rs) ─────────────────────

#[derive(Serialize, Deserialize)]
struct SerializableProfiles {
    profiles: HashMap<[u8; 32], HashMap<u32, (u64, u64)>>,
}

impl SerializableProfiles {
    fn into_profiles(self) -> HashMap<B256, BranchProfile> {
        self.profiles
            .into_iter()
            .map(|(hash_bytes, branches)| {
                let hash = B256::from(hash_bytes);
                let profile = BranchProfile { branches };
                (hash, profile)
            })
            .collect()
    }
}

// ── Skeleton helpers (same as skeleton_bench.rs) ─────────────────────────────

fn extract_opcode_skeleton(bytes: &[u8]) -> Vec<u8> {
    let mut skeleton = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        let op = bytes[i];
        skeleton.push(op);
        i += 1;
        if op >= 0x60 && op <= 0x7f {
            i += (op - 0x5f) as usize;
        }
    }
    skeleton
}

fn hash_bytes(bytes: &[u8]) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    bytes.hash(&mut hasher);
    hasher.finish()
}

fn opt_tag(opt: OptimizationLevel) -> &'static str {
    match opt {
        OptimizationLevel::None => "o0",
        OptimizationLevel::Less => "o1",
        OptimizationLevel::Default => "o2",
        OptimizationLevel::Aggressive => "o3",
    }
}

// ── Skeleton AOT Cache ───────────────────────────────────────────────────────

struct SkeletonCacheArtifacts {
    symbol: String,
    object: PathBuf,
    library: PathBuf,
}

fn skeleton_cache_artifacts(cache_dir: &Path, skeleton_hash: u64) -> SkeletonCacheArtifacts {
    let tag = opt_tag(OPT);
    let spec_tag = format!("{:?}", bin_common::ETH_SPEC).to_lowercase();
    let key = format!("skel_{skeleton_hash:016x}__{spec_tag}__{tag}");
    let stem = cache_dir.join(&key);
    SkeletonCacheArtifacts {
        symbol: format!("skel_{skeleton_hash:016x}"),
        object: stem.with_extension("o"),
        library: stem.with_extension(std::env::consts::DLL_EXTENSION),
    }
}

/// PGO variant: separate cache path with `_pgo` suffix.
fn skeleton_cache_artifacts_pgo(cache_dir: &Path, skeleton_hash: u64) -> SkeletonCacheArtifacts {
    let tag = opt_tag(OPT);
    let spec_tag = format!("{:?}", bin_common::ETH_SPEC).to_lowercase();
    let key = format!("skel_{skeleton_hash:016x}__{spec_tag}__{tag}_pgo");
    let stem = cache_dir.join(&key);
    SkeletonCacheArtifacts {
        symbol: format!("skel_{skeleton_hash:016x}"),
        object: stem.with_extension("o"),
        library: stem.with_extension(std::env::consts::DLL_EXTENSION),
    }
}

fn compile_skeleton_to_cache(
    bytecode: &[u8],
    variance: &SkeletonVariance,
    artifacts: &SkeletonCacheArtifacts,
) -> Result<(), String> {
    if let Some(parent) = artifacts.object.parent() {
        std::fs::create_dir_all(parent).ok();
    }
    let context = Box::leak(Box::new(revmc::llvm::inkwell::context::Context::create()));
    let backend =
        EvmLlvmBackend::new(context, true, OPT).map_err(|e| format!("AOT backend: {e}"))?;
    let mut compiler = EvmCompiler::new(backend);
    compiler
        .translate_skeleton(&artifacts.symbol, bytecode, bin_common::ETH_SPEC, variance)
        .map_err(|e| format!("translate_skeleton: {e}"))?;
    compiler
        .write_object_to_file(&artifacts.object)
        .map_err(|e| format!("write: {e}"))?;
    revmc::Linker::new()
        .link(&artifacts.library, [&artifacts.object])
        .map_err(|e| format!("link: {e}"))?;
    Ok(())
}

fn compile_skeleton_pgo(
    bytecode: &[u8],
    variance: &SkeletonVariance,
    artifacts: &SkeletonCacheArtifacts,
    profile: &BranchProfile,
) -> Result<(), String> {
    if let Some(parent) = artifacts.object.parent() {
        std::fs::create_dir_all(parent).ok();
    }
    let context = Box::leak(Box::new(revmc::llvm::inkwell::context::Context::create()));
    let backend =
        EvmLlvmBackend::new(context, true, OPT).map_err(|e| format!("AOT backend: {e}"))?;
    let mut compiler = EvmCompiler::new(backend);
    compiler.set_branch_profile(profile.clone());
    compiler
        .translate_skeleton(&artifacts.symbol, bytecode, bin_common::ETH_SPEC, variance)
        .map_err(|e| format!("translate_skeleton: {e}"))?;
    compiler
        .write_object_to_file(&artifacts.object)
        .map_err(|e| format!("write: {e}"))?;
    revmc::Linker::new()
        .link(&artifacts.library, [&artifacts.object])
        .map_err(|e| format!("link: {e}"))?;
    Ok(())
}

fn load_skeleton_cached(
    artifacts: &SkeletonCacheArtifacts,
) -> Result<(RawEvmCompilerFn, libloading::Library), String> {
    let library = unsafe { libloading::Library::new(&artifacts.library) }
        .map_err(|e| format!("dlopen: {e}"))?;
    let symbol = unsafe { library.get::<RawEvmCompilerFn>(artifacts.symbol.as_bytes()) }
        .map_err(|e| format!("dlsym: {e}"))?;
    let function = *symbol;
    drop(symbol);
    Ok((function, library))
}

// ── Profile merging ──────────────────────────────────────────────────────────

/// Merge branch profiles from all skeleton group members into a single profile.
/// Since all members share the same opcode skeleton, JUMPI positions are at the
/// same PCs — we simply sum the taken/not-taken counts.
fn merge_profiles(
    members: &[(B256, Vec<u8>)],
    all_profiles: &HashMap<B256, BranchProfile>,
) -> BranchProfile {
    let mut merged = BranchProfile::new();
    for (hash, _) in members {
        if let Some(p) = all_profiles.get(hash) {
            for (&pc, &(t, nt)) in &p.branches {
                let entry = merged.branches.entry(pc).or_insert((0, 0));
                entry.0 += t;
                entry.1 += nt;
            }
        }
    }
    merged
}

// ── Skeleton Handler ─────────────────────────────────────────────────────────

struct SkeletonHandler {
    per_hash_fns: Arc<HashMap<B256, RawEvmCompilerFn>>,
    skeleton_dispatch: Arc<HashMap<B256, (EvmCompilerFn, Vec<u8>)>>,
}

impl Handler for SkeletonHandler {
    type Evm = BenchEvm;
    type Error = BenchError;
    type HaltReason = op_revm::OpHaltReason;

    fn run_exec_loop(
        &mut self,
        evm: &mut Self::Evm,
        first_frame_input: revm::interpreter::interpreter_action::FrameInit,
    ) -> Result<FrameResult, Self::Error> {
        let res = evm.frame_init(first_frame_input)?;
        if let ItemOrResult::Result(frame_result) = res {
            return Ok(frame_result);
        }
        loop {
            let call_or_result = self.run_skeleton_or_jit(evm)?;
            let result = match call_or_result {
                ItemOrResult::Item(init) => match evm.frame_init(init)? {
                    ItemOrResult::Item(_) => continue,
                    ItemOrResult::Result(result) => result,
                },
                ItemOrResult::Result(result) => result,
            };
            if let Some(result) = evm.frame_return_result(result)? {
                return Ok(result);
            }
        }
    }
}

impl SkeletonHandler {
    fn run_skeleton_or_jit(
        &self,
        evm: &mut BenchEvm,
    ) -> Result<
        ItemOrResult<revm::interpreter::interpreter_action::FrameInit, FrameResult>,
        BenchError,
    > {
        let (ctx, frame_stack) = (&mut evm.0.ctx, &mut evm.0.frame_stack);
        let frame = frame_stack.get();

        if !bin_common::should_lookup_jit(
            frame.data.is_create(),
            frame.interpreter.input.bytecode_address,
            frame.interpreter.bytecode.is_empty(),
        ) {
            drop((ctx, frame_stack));
            return Ok(evm.frame_run()?);
        }

        let bytecode_hash = frame.interpreter.bytecode.get_or_calculate_hash();

        let action =
            if let Some((skel_fn, data_table)) = self.skeleton_dispatch.get(&bytecode_hash) {
                unsafe {
                    skel_fn.call_with_interpreter_data(
                        &mut frame.interpreter,
                        ctx,
                        data_table.as_ptr(),
                    )
                }
            } else if let Some(&raw_fn) = self.per_hash_fns.get(&bytecode_hash) {
                let f = EvmCompilerFn::new(raw_fn);
                unsafe { f.call_with_interpreter(&mut frame.interpreter, ctx) }
            } else {
                drop((ctx, frame_stack));
                return Ok(evm.frame_run()?);
            };

        let result = frame
            .process_next_action::<_, BenchError>(ctx, action)
            .inspect(|i| {
                if i.is_result() {
                    frame.set_finished(true);
                }
            })?;
        Ok(result)
    }
}

// ── Execution Helper ─────────────────────────────────────────────────────────

struct ExecResults {
    results: Vec<(bool, u64)>,
    dur: Duration,
}

fn execute_block(
    loader: &BinLoader,
    chain_id: Option<u64>,
    mut run_tx: impl FnMut(&mut BenchEvm) -> (bool, u64),
) -> ExecResults {
    let cfg = build_op_cfg(chain_id);
    let dummy_tx = OpTransaction::builder().build_fill();
    let mut evm: BenchEvm = {
        let ctx = OpCtx::<EmptyDB>::op()
            .with_cfg(cfg)
            .with_db(loader.build_cache_db())
            .with_tx(dummy_tx);
        op_revm::OpEvm::new(ctx, ())
    };

    let mut results = Vec::with_capacity(loader.tx_count());
    let t0 = Instant::now();

    for tx_bin in loader.raw_txs() {
        if tx_bin.tx_type == 0x7e {
            results.push((true, 0));
            continue;
        }
        evm.0.ctx.tx = build_op_tx(tx_bin);
        results.push(run_tx(&mut evm));
    }

    ExecResults {
        results,
        dur: t0.elapsed(),
    }
}

fn median(durations: &[Duration]) -> Duration {
    let mut sorted: Vec<Duration> = durations.to_vec();
    sorted.sort();
    sorted[sorted.len() / 2]
}

// ── Analyzed skeleton group ──────────────────────────────────────────────────

struct AnalyzedGroup {
    skel_hash: u64,
    members: Vec<(B256, Vec<u8>)>,
    variance: SkeletonVariance,
}

// ── Main ─────────────────────────────────────────────────────────────────────

fn main() {
    let dir = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "/home/ubuntu/sipeng/bench_data".into());
    let bench_dir = Path::new(&dir);
    let block: u64 = std::env::args()
        .nth(2)
        .and_then(|s| s.parse().ok())
        .unwrap_or(38004930);
    let cache_dir = PathBuf::from("./jit_cache");
    let pgo_cache_dir = PathBuf::from("./jit_cache_pgo");

    println!("=== PGO Branch Profiling Benchmark ===");
    println!("Block {block} | Cache: {}\n", cache_dir.display());

    // ── Phase 1: Load block data ─────────────────────────────────────────
    let loader = BinLoader::new(bench_dir, block).unwrap_or_else(|e| {
        eprintln!("Failed to load block data: {e}");
        std::process::exit(1);
    });
    println!(
        "Loaded {} accounts, {} codes, {} txs",
        loader.account_count(),
        loader.code_count(),
        loader.tx_count()
    );

    // ── Phase 2: Load branch profiles ────────────────────────────────────
    let profile_path = format!("/tmp/branch_profile_{block}.bin");
    let profile_data = std::fs::read(&profile_path).unwrap_or_else(|e| {
        eprintln!("Failed to read profile {profile_path}: {e}");
        eprintln!("Run `collect_profile` first to generate the profile.");
        std::process::exit(1);
    });
    let serializable: SerializableProfiles =
        bincode::deserialize(&profile_data).expect("deserialize profile");
    let all_profiles = serializable.into_profiles();
    println!(
        "Loaded profiles for {} contracts from {profile_path}",
        all_profiles.len()
    );

    // ── Phase 3: Skeleton grouping ───────────────────────────────────────
    let all_codes: HashMap<B256, Vec<u8>> = loader
        .code_values()
        .iter()
        .filter(|(_, bc)| !bc.is_empty())
        .map(|(h, bc)| (*h, bc.original_byte_slice().to_vec()))
        .collect();

    let mut skeleton_groups_raw: HashMap<u64, Vec<(B256, Vec<u8>)>> = HashMap::new();
    for (hash, bytes) in &all_codes {
        let skel = extract_opcode_skeleton(bytes);
        let skel_hash = hash_bytes(&skel);
        skeleton_groups_raw
            .entry(skel_hash)
            .or_default()
            .push((*hash, bytes.clone()));
    }

    let mut dup_groups: Vec<_> = skeleton_groups_raw
        .into_iter()
        .filter(|(_, members)| members.len() >= 2)
        .collect();
    dup_groups.sort_by_key(|(_, m)| std::cmp::Reverse(m.len()));

    if dup_groups.is_empty() {
        println!("No duplicated skeletons found.");
        return;
    }

    let analyzed: Vec<AnalyzedGroup> = dup_groups
        .into_iter()
        .map(|(skel_hash, members)| {
            let refs: Vec<&[u8]> = members.iter().map(|(_, b)| b.as_slice()).collect();
            let variance = analyze_skeleton_group(&refs);
            AnalyzedGroup {
                skel_hash,
                members,
                variance,
            }
        })
        .collect();

    let skeleton_member_hashes: HashSet<B256> = analyzed
        .iter()
        .flat_map(|g| g.members.iter().map(|(h, _)| *h))
        .collect();
    let n_groups = analyzed.len();
    let total_skeleton_members = skeleton_member_hashes.len();

    println!(
        "\n{n_groups} skeleton groups, {total_skeleton_members} contracts (of {})",
        all_codes.len()
    );

    // ── Phase 4: Compilation ─────────────────────────────────────────────

    // 4a. Shared base: non-skeleton per-hash (with AOT cache)
    let base_code_map: HashMap<B256, Bytecode> = loader
        .code_values()
        .iter()
        .filter(|(h, _)| !skeleton_member_hashes.contains(*h))
        .map(|(h, bc)| (*h, bc.clone()))
        .collect();

    println!(
        "\n--- Shared base: {} non-skeleton per-hash (with cache) ---",
        base_code_map.len()
    );
    let compiled_base = compile_all_contracts_with_cache(&base_code_map, OPT, &cache_dir);
    println!("  {} functions loaded", compiled_base.functions.len());
    let non_skeleton_fns = compiled_base.functions.clone();

    // 4b. Skeleton (no PGO) — compile or load from standard cache
    println!("\n--- Skeleton (no PGO): {n_groups} groups ---");
    let (skeleton_dispatch, _skeleton_libs) =
        compile_and_load_skeletons(&analyzed, &cache_dir, None, &HashMap::new());

    // 4c. Skeleton + PGO — compile or load from PGO cache
    println!("\n--- Skeleton + PGO: {n_groups} groups ---");
    let (skeleton_pgo_dispatch, _pgo_libs) =
        compile_and_load_skeletons(&analyzed, &pgo_cache_dir, Some(&all_profiles), &all_profiles);

    // ── Phase 5: Execution (warmup + measured) ───────────────────────────
    println!(
        "\n--- Execution ({WARMUP_ROUNDS} warmup + {MEASURE_ROUNDS} measured) ---"
    );
    let chain_id = loader.raw_txs().first().and_then(|tx| tx.chain_id);

    let sd_nopgo = Arc::new(skeleton_dispatch);
    let sd_pgo = Arc::new(skeleton_pgo_dispatch);

    // Warmup
    for _ in 0..WARMUP_ROUNDS {
        execute_block(&loader, chain_id, |evm| {
            let mut h = NativeHandler;
            match h.run(evm) {
                Ok(r) => extract_gas(&r),
                Err(_) => (false, 0),
            }
        });
        execute_block(&loader, chain_id, |evm| {
            let mut h = SkeletonHandler {
                per_hash_fns: non_skeleton_fns.clone(),
                skeleton_dispatch: sd_nopgo.clone(),
            };
            match h.run(evm) {
                Ok(r) => extract_gas(&r),
                Err(_) => (false, 0),
            }
        });
        execute_block(&loader, chain_id, |evm| {
            let mut h = SkeletonHandler {
                per_hash_fns: non_skeleton_fns.clone(),
                skeleton_dispatch: sd_pgo.clone(),
            };
            match h.run(evm) {
                Ok(r) => extract_gas(&r),
                Err(_) => (false, 0),
            }
        });
    }
    println!("  Warmup done.");

    // Measured rounds
    let mut native_durs = Vec::with_capacity(MEASURE_ROUNDS);
    let mut skel_durs = Vec::with_capacity(MEASURE_ROUNDS);
    let mut pgo_durs = Vec::with_capacity(MEASURE_ROUNDS);
    let mut native_results = None;
    let mut skel_results = None;
    let mut pgo_results = None;

    for round in 0..MEASURE_ROUNDS {
        let native = execute_block(&loader, chain_id, |evm| {
            let mut h = NativeHandler;
            match h.run(evm) {
                Ok(r) => extract_gas(&r),
                Err(_) => (false, 0),
            }
        });
        native_durs.push(native.dur);

        let skel = execute_block(&loader, chain_id, |evm| {
            let mut h = SkeletonHandler {
                per_hash_fns: non_skeleton_fns.clone(),
                skeleton_dispatch: sd_nopgo.clone(),
            };
            match h.run(evm) {
                Ok(r) => extract_gas(&r),
                Err(_) => (false, 0),
            }
        });
        skel_durs.push(skel.dur);

        let pgo = execute_block(&loader, chain_id, |evm| {
            let mut h = SkeletonHandler {
                per_hash_fns: non_skeleton_fns.clone(),
                skeleton_dispatch: sd_pgo.clone(),
            };
            match h.run(evm) {
                Ok(r) => extract_gas(&r),
                Err(_) => (false, 0),
            }
        });
        pgo_durs.push(pgo.dur);

        // Save last round results for correctness check
        if round == MEASURE_ROUNDS - 1 {
            native_results = Some(native.results);
            skel_results = Some(skel.results);
            pgo_results = Some(pgo.results);
        }
    }

    // ── Phase 6: Report ──────────────────────────────────────────────────
    let med_native = median(&native_durs);
    let med_skel = median(&skel_durs);
    let med_pgo = median(&pgo_durs);

    let native_ms = med_native.as_secs_f64() * 1000.0;
    let skel_ms = med_skel.as_secs_f64() * 1000.0;
    let pgo_ms = med_pgo.as_secs_f64() * 1000.0;

    let skel_ratio = native_ms / skel_ms;
    let pgo_ratio = native_ms / pgo_ms;

    println!();
    println!("{:<22} | {:>12} | {:>10}", "Mode", "Median (ms)", "vs Native");
    println!("{:-<22}-+-{:-<12}-+-{:-<10}", "", "", "");
    println!(
        "{:<22} | {:>12.1} | {:>10.2}x",
        "Native", native_ms, 1.0f64
    );
    println!(
        "{:<22} | {:>12.1} | {:>10.2}x",
        "Skeleton (no PGO)", skel_ms, skel_ratio
    );
    println!(
        "{:<22} | {:>12.1} | {:>10.2}x",
        "Skeleton + PGO", pgo_ms, pgo_ratio
    );

    // ── Phase 7: Correctness check ───────────────────────────────────────
    let native_res = native_results.unwrap();
    let skel_res = skel_results.unwrap();
    let pgo_res = pgo_results.unwrap();

    let gas_native: u64 = native_res.iter().map(|(_, g)| g).sum();
    let gas_skel: u64 = skel_res.iter().map(|(_, g)| g).sum();
    let gas_pgo: u64 = pgo_res.iter().map(|(_, g)| g).sum();

    let mut mismatches_skel = 0u32;
    let mut mismatches_pgo = 0u32;
    for (i, ((nr, sr), pr)) in native_res
        .iter()
        .zip(skel_res.iter())
        .zip(pgo_res.iter())
        .enumerate()
    {
        if nr != sr {
            mismatches_skel += 1;
            eprintln!(
                "  MISMATCH tx[{i}]: native=({},{}) skeleton=({},{})",
                nr.0, nr.1, sr.0, sr.1
            );
        }
        if nr != pr {
            mismatches_pgo += 1;
            eprintln!(
                "  MISMATCH tx[{i}]: native=({},{}) pgo=({},{})",
                nr.0, nr.1, pr.0, pr.1
            );
        }
    }

    println!("\n=== Correctness ===");
    println!(
        "  Skeleton: {}/{} match, gas={gas_skel} {}",
        native_res.len() - mismatches_skel as usize,
        native_res.len(),
        if gas_native == gas_skel {
            "EQUAL"
        } else {
            "DIFFER!"
        }
    );
    println!(
        "  PGO:      {}/{} match, gas={gas_pgo} {}",
        native_res.len() - mismatches_pgo as usize,
        native_res.len(),
        if gas_native == gas_pgo {
            "EQUAL"
        } else {
            "DIFFER!"
        }
    );

    if mismatches_skel == 0 && mismatches_pgo == 0 {
        println!("\n  PASS");
    }

    println!("\nDone.");
}

// ── Skeleton compilation + loading ───────────────────────────────────────────

/// Compile and load skeleton groups. Returns the dispatch table and libraries.
/// If `profiles` is Some, PGO compilation is used (merged profile per group).
fn compile_and_load_skeletons(
    analyzed: &[AnalyzedGroup],
    cache_dir: &Path,
    profiles: Option<&HashMap<B256, BranchProfile>>,
    all_profiles: &HashMap<B256, BranchProfile>,
) -> (
    HashMap<B256, (EvmCompilerFn, Vec<u8>)>,
    Vec<libloading::Library>,
) {
    let mut skeleton_dispatch: HashMap<B256, (EvmCompilerFn, Vec<u8>)> = HashMap::new();
    let mut skeleton_libs: Vec<libloading::Library> = Vec::new();

    let artifacts_fn = if profiles.is_some() {
        skeleton_cache_artifacts_pgo
    } else {
        skeleton_cache_artifacts
    };

    // Phase 1: try loading from cache, collect misses
    let mut cached: Vec<(usize, RawEvmCompilerFn)> = Vec::new();
    let mut to_compile: Vec<usize> = Vec::new();
    for (i, g) in analyzed.iter().enumerate() {
        let artifacts = artifacts_fn(cache_dir, g.skel_hash);
        match load_skeleton_cached(&artifacts) {
            Ok((f, lib)) => {
                skeleton_libs.push(lib);
                cached.push((i, f));
            }
            Err(_) => to_compile.push(i),
        }
    }
    println!(
        "  cache: {} hit, {} to compile",
        cached.len(),
        to_compile.len()
    );

    // Phase 2: compile misses (parallel)
    let compiled: Vec<(usize, Result<(), String>)> = std::thread::scope(|s| {
        let handles: Vec<_> = to_compile
            .iter()
            .map(|&i| {
                let g = &analyzed[i];
                let artifacts = artifacts_fn(cache_dir, g.skel_hash);
                let merged_profile = profiles.map(|_| merge_profiles(&g.members, all_profiles));
                s.spawn(move || {
                    let result = if let Some(ref profile) = merged_profile {
                        compile_skeleton_pgo(&g.members[0].1, &g.variance, &artifacts, profile)
                    } else {
                        compile_skeleton_to_cache(&g.members[0].1, &g.variance, &artifacts)
                    };
                    (i, result)
                })
            })
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });

    // Phase 3: load compiled results
    for (i, result) in compiled {
        let g = &analyzed[i];
        let artifacts = artifacts_fn(cache_dir, g.skel_hash);
        match result {
            Ok(()) => match load_skeleton_cached(&artifacts) {
                Ok((f, lib)) => {
                    skeleton_libs.push(lib);
                    cached.push((i, f));
                }
                Err(e) => eprintln!("  WARN: skel {:016x} load failed: {e}", g.skel_hash),
            },
            Err(e) => eprintln!("  WARN: skel {:016x} compile failed: {e}", g.skel_hash),
        }
    }

    // Phase 4: build data tables
    for (i, raw_fn) in &cached {
        let g = &analyzed[*i];
        let skel_fn = EvmCompilerFn::new(*raw_fn);
        for (hash, bytes) in &g.members {
            let table = build_data_table(bytes, &g.variance);
            skeleton_dispatch.insert(*hash, (skel_fn, table.data));
        }
    }

    println!(
        "  {} groups loaded, {} contracts dispatched",
        cached.len(),
        skeleton_dispatch.len()
    );

    (skeleton_dispatch, skeleton_libs)
}
